import java.util.NoSuchElementException;

public class Solution {
    static class FilaCircular {
        private final int[] dados;
        private int inicio, tamanho;

        FilaCircular(int capacidade) { dados = new int[capacidade]; }

        // O fim é (inicio + tamanho) % capacidade: o contador evita a ambiguidade cheia/vazia.
        boolean offer(int v) {
            if (isFull()) return false;
            dados[(inicio + tamanho) % dados.length] = v;
            tamanho++;
            return true;
        }

        int poll() {
            int v = peek();
            inicio = (inicio + 1) % dados.length;
            tamanho--;
            return v;
        }

        int peek() {
            if (isEmpty()) throw new NoSuchElementException("fila vazia");
            return dados[inicio];
        }

        int size() { return tamanho; }
        boolean isEmpty() { return tamanho == 0; }
        boolean isFull() { return tamanho == dados.length; }
    }
}

