import java.util.NoSuchElementException;

class SolutionTest {
    @Test void fifo() {
        var f = new Solution.FilaCircular(3);
        assertTrue(f.offer(1)); assertTrue(f.offer(2)); assertTrue(f.offer(3));
        assertFalse(f.offer(4));
        assertTrue(f.isFull());
        assertEquals(1, f.poll());
        assertEquals(2, f.peek());
    }

    @Test void daAVolta() {
        var f = new Solution.FilaCircular(2);
        for (int i = 0; i < 1000; i++) {
            assertTrue(f.offer(i));
            assertEquals(i, f.poll());
        }
        assertTrue(f.isEmpty());
    }

    @Test void vazia() {
        var f = new Solution.FilaCircular(1);
        assertThrows(NoSuchElementException.class, f::poll);
        assertThrows(NoSuchElementException.class, f::peek);
    }
}

