import java.util.*;

public class Solution {
    // BFS: a primeira vez que um vértice é alcançado é pelo caminho mais curto. O(V + E).
    static int[] distancias(int n, int[][] arestas, int origem) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] e : arestas) {
            adj.get(e[0]).add(e[1]);
            adj.get(e[1]).add(e[0]);
        }
        int[] dist = new int[n];
        Arrays.fill(dist, -1);
        ArrayDeque<Integer> fila = new ArrayDeque<>();
        dist[origem] = 0;
        fila.add(origem);
        while (!fila.isEmpty()) {
            int u = fila.poll();
            for (int v : adj.get(u)) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    fila.add(v);
                }
            }
        }
        return dist;
    }
}

