import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void pequeno() {
        int[][] e = {{0, 1}, {0, 2}, {1, 3}, {2, 3}, {3, 4}};
        assertArrayEquals(new int[]{0, 1, 1, 2, 3}, Solution.distancias(5, e, 0));
    }

    @Test void inalcancavel() {
        assertArrayEquals(new int[]{-1, 0, 1, -1}, Solution.distancias(4, new int[][]{{1, 2}}, 1));
    }

    @Test void caminhoLongo() {
        int n = 200_000;
        int[][] e = new int[n - 1][];
        for (int i = 0; i + 1 < n; i++) e[i] = new int[]{i, i + 1};
        assertEquals(n - 1, Solution.distancias(n, e, 0)[n - 1]);
    }
}
